package main

import (
	"fmt"
	"log"
	"os"

	"github.com/anthnel/devdesk/internal/app"
	"github.com/anthnel/devdesk/internal/config"
	"github.com/anthnel/devdesk/internal/ui/setup"
	"github.com/anthnel/devdesk/internal/ui/theme"
	tea "charm.land/bubbletea/v2"
)

func getCurrentContextName() string {
	ctx, err := config.GetCurrentContext()
	if err != nil || ctx == "" {
		return "default"
	}
	return ctx
}

// main runs the TUI, with one exception: `dk setup`.
//
// `dk mcp` served the MCP server on stdio (§3.38) and is gone with it (§3.61):
// the server now lives in this process, over HTTP, started by the router. What
// that deleted was the flag set, the argument dispatch, and the ordering
// constraint that used to sit here — everything below writes to stdout, and in
// stdio stdout *was* the protocol channel, so a single warning printed before
// the server started made the client report a JSON parse error naming nothing.
// Over HTTP the two do not share a channel, so that constraint is gone rather
// than relaxed.
//
// `setup` is not a reversal of "no subcommand any more": it is one literal
// case, not a flag-parsing framework, and it runs before any context is
// loaded — the one thing the TUI itself cannot do for a user who has none yet.
func main() {
	if len(os.Args) > 1 && os.Args[1] == "setup" {
		if err := setup.Run(); err != nil {
			fmt.Fprintln(os.Stderr, "setup failed:", err)
			os.Exit(1)
		}
		return
	}
	runTUI()
}

func runTUI() {
	// Force TrueColor if Windows Terminal is detected (WSL does not propagate COLORTERM)
	if os.Getenv("WT_SESSION") != "" && os.Getenv("COLORTERM") == "" {
		_ = os.Setenv("COLORTERM", "truecolor")
	}

	// Load the configuration
	cfg, err := config.Load()
	if err != nil {
		fmt.Printf("Error loading config: %v\n", err)
		fmt.Println("Using default configuration.")
		cfg = config.Default()
	}

	// Create the config directory if it does not exist
	if err := config.EnsureConfigDir(); err != nil {
		fmt.Printf("Warning: Could not create config directory: %v\n", err)
	}

	// Always enable logging to a file to avoid polluting the TUI interface
	logFile, err := tea.LogToFile(cfg.App.LogFile, "debug")
	if err != nil {
		fmt.Printf("Warning: Could not create log file: %v\n", err)
	} else {
		defer func() { _ = logFile.Close() }()
		log.Printf("=== DevDesk Started ===")
		log.Printf("Config loaded from context: %s", getCurrentContextName())
		log.Printf("Log file: %s", cfg.App.LogFile)
		log.Printf("DEBUG mode: %v", len(os.Getenv("DEBUG")) > 0)
	}

	// Load and apply the saved theme
	if cfg.App.Theme != "" && cfg.App.Theme != "dark" {
		t, err := theme.LoadTheme(cfg.App.Theme)
		if err != nil {
			log.Printf("Warning: Could not load theme '%s': %v, using default", cfg.App.Theme, err)
		} else {
			theme.ApplyTheme(t)
			theme.CurrentThemeName = cfg.App.Theme
			log.Printf("Theme loaded: %s", cfg.App.Theme)
		}
	}

	theme.SetGaugeGlyph(cfg.App.GaugeGlyph)

	// Create the application with the router
	m := app.New(cfg)

	// Start the Bubble Tea program. The router's View asks for the alternate
	// screen; main.go sets no terminal state.
	p := tea.NewProgram(m)

	// The router needs the handle before the loop starts: an MCP request
	// reaches Update() through p.Send, and there is no other legal door
	// (Rule 110). Written here, once, while nothing else is running.
	m.AttachProgram(p)

	if _, err := p.Run(); err != nil {
		fmt.Printf("Error running application: %v\n", err)
		os.Exit(1)
	}
}
package main

import (
	"strings"
	"sync"
	"testing"
	"time"

	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"
)

type safeBuf struct {
	mu sync.Mutex
	sb strings.Builder
}

func (s *safeBuf) Write(p []byte) (int, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.sb.Write(p)
}

func (s *safeBuf) String() string {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.sb.String()
}

// colorModel renders one coloured word, enough to see which profile the
// program writes.
type colorModel struct{}

func (colorModel) Init() tea.Cmd                         { return nil }
func (m colorModel) Update(tea.Msg) (tea.Model, tea.Cmd) { return m, nil }
func (colorModel) View() tea.View {
	return tea.NewView(lipgloss.NewStyle().Foreground(lipgloss.Color("#ff8800")).Render("hello"))
}

// runAt runs a real tea.Program with opts until its first frame shows, and
// returns what it wrote.
func runAt(t *testing.T, opts ...tea.ProgramOption) string {
	t.Helper()
	out := &safeBuf{}
	opts = append([]tea.ProgramOption{
		tea.WithInput(nil), tea.WithOutput(out), tea.WithWindowSize(40, 5), tea.WithoutSignalHandler(),
	}, opts...)
	p := tea.NewProgram(colorModel{}, opts...)
	go func() {
		deadline := time.Now().Add(5 * time.Second)
		for !strings.Contains(out.String(), "hello") && time.Now().Before(deadline) {
			time.Sleep(10 * time.Millisecond)
		}
		p.Quit()
	}()
	if _, err := p.Run(); err != nil {
		t.Fatal(err)
	}
	return out.String()
}

// Windows Terminal under WSL does not propagate COLORTERM, so main forces
// TrueColor there; a forced profile bypasses the detection that honours
// NO_COLOR, so NO_COLOR must switch the forcing off (DEVDESK-201, H4).
// Each forcing is applied to a real program and the output is read.
func TestForcedColorProfile(t *testing.T) {
	for _, tc := range []struct {
		name      string
		env       map[string]string
		wantForce bool
	}{
		{"windows terminal", map[string]string{"WT_SESSION": "1"}, true},
		{"windows terminal with COLORTERM already set", map[string]string{"WT_SESSION": "1", "COLORTERM": "truecolor"}, true},
		{"windows terminal with NO_COLOR", map[string]string{"WT_SESSION": "1", "NO_COLOR": "1"}, false},
		{"plain terminal", map[string]string{}, false},
		{"COLORTERM alone is not forced", map[string]string{"COLORTERM": "truecolor"}, false},
		{"NO_COLOR alone", map[string]string{"NO_COLOR": "1"}, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p, forced := forcedColorProfile(func(k string) string { return tc.env[k] })
			if forced != tc.wantForce {
				t.Fatalf("forced = %v, want %v", forced, tc.wantForce)
			}
			if !forced {
				return
			}
			if got := runAt(t, tea.WithColorProfile(p)); !strings.Contains(got, "38;2;255;136;0") {
				t.Errorf("the forced profile did not give TrueColor output: %q", got)
			}
		})
	}
}
